premise_signature:
{p p' q q' : Point}
    (hp : pointEquiv p p') (hq : pointEquiv q q') :
    pointEquiv (pointAdd p q) (pointAdd p' q')

{a b : Fraction}
    (hab : Fraction.lt a b) (c : Fraction) :
    Fraction.lt (Fraction.add c a) (Fraction.add c b)

{a b : Fraction}
    (hab : Fraction.lt a b) (c : Fraction) :
    Fraction.lt (Fraction.add a c) (Fraction.add b c)

{a a' b b' : EndpointCauchyName} {R : Fraction}
    (ha : NameEquiv a a') (hb : NameEquiv b b') :
    NameBound a b R → NameBound a' b' R

{a a' b b' : EndpointCauchyName} {R : Fraction}
    (ha : NameEquiv a a') (hb : NameEquiv b b') :
    NameBound a b R ↔ NameBound a' b' R

{a b c : EndpointCauchyName} {R S : Fraction}
    (hab : NameBound a b R) (hbc : NameBound b c S) :
    NameBound a c (Fraction.add R S)

{a b : Fraction} {p q : Point}
    (ha : Fraction.equiv a b) (hp : pointEquiv p q) :
    pointEquiv (pointScale a p) (pointScale b q)

{p p' q q' : Point}
    (hp : pointEquiv p p') (hq : pointEquiv q q') :
    pointEquiv (pointSub p q) (pointSub p' q')

{s s' t t' : Point × Point}
    (hs : stateEquiv s s') (ht : stateEquiv t t') :
    stateEquiv (stateSub s t) (stateSub s' t')

{d e : Fraction} {s t : Point × Point}
    (hd : Fraction.equiv d e) (hs : stateEquiv s t) (w : Fraction) :
    stateEquiv (cell (linearField w) d s) (cell (linearField w) e t)

{a b : Fraction}
    (hab : Fraction.lt a b) (c : Fraction) (hc : 0 < c.num) :
    Fraction.lt (Fraction.mul c a) (Fraction.mul c b)
